import { LearnHub } from '@learnhub/sdk';

const client = new LearnHub({
  apiKey: process.env.LEARNHUB_KEY
});

// Fetch course catalog
const courses = await client.courses.list({
  category: 'technology',
  level: 'beginner',
  limit: 10
});

// Enroll user in course
await client.enrollments.create({
  userId: 'user_123',
  courseId: courses[0].id
});

console.log('Enrollment successful!');
